/**
 * HudArt — registry for the supplied blank wooden HUD artwork
 * (public/assets/images/ui/hud/, generated by scripts/prepare-hud-assets.mjs).
 *
 * Every entry carries the geometry MEASURED from the artwork's pixels
 * (scripts/measure-hud-art.mjs — alpha trim + centre-tone scans), as
 * fractions of the trimmed texture:
 *   aspect — trimmed width / height (display sizes derive from it, so the
 *            art is never stretched)
 *   inner  — the recessed writing window, clear of the carved frame,
 *            leaves, bolts and scroll ends
 *   cells  — the progress panel's REAL compartment boundaries (measured:
 *            narrow | wide | narrow, dividers at 0.240/0.727 — NOT thirds)
 *
 * The same fractions drive the procedural stand-ins (ensureHudArtFallback)
 * so environments where the PNGs cannot be fetched (headless tests) render
 * with identical layout ratios — the project's established fallback pattern
 * (see QuestionCard.ensureQuestionCardTexture).
 *
 * The wide single-cell strip asset is deliberately not used: the individual
 * panels compose a cleaner top bar and a second backing bar would only add
 * thickness behind already-framed artwork.
 */

export const HUD_ART = {
  pauseBtn: {
    key: 'hud-pause-btn', file: 'pause-button-bg.png', aspect: 1096 / 1110,
    iconDisk: 0.5 // usable inner disk (Ø) for the code-drawn icon
  },
  soundBtn: {
    key: 'hud-sound-btn', file: 'sound-button-bg.png', aspect: 1017 / 1011,
    iconDisk: 0.5
  },
  level: {
    key: 'hud-level-panel', file: 'level-panel-bg.png', aspect: 2144 / 563,
    inner: { x0: 0.109, x1: 0.799, y0: 0.281, y1: 0.702 } // light parchment, scroll right
  },
  progress: {
    key: 'hud-progress-panel', file: 'progress-panel-bg.png', aspect: 2143 / 422,
    inner: { y0: 0.341, y1: 0.746 },
    cells: {
      question: { x0: 0.113, x1: 0.2403 }, // narrow left cell
      timer: { x0: 0.273, x1: 0.727 },     // wide middle cell — the MM:SS read
      stars: { x0: 0.7597, x1: 0.887 }     // narrow right cell
    }
  },
  hearts: {
    key: 'hud-hearts-panel', file: 'hearts-panel-bg.png', aspect: 1707 / 523,
    inner: { x0: 0.096, x1: 0.887, y0: 0.27, y1: 0.753 } // dark centre
  },
  shots: {
    key: 'hud-shots-panel', file: 'shots-panel-bg.png', aspect: 1626 / 648,
    inner: { x0: 0.143, x1: 0.820, y0: 0.377, y1: 0.704 } // light tan centre
  },
  score: {
    key: 'hud-score-panel', file: 'score-panel-bg.png', aspect: 1735 / 680,
    inner: { x0: 0.130, x1: 0.856, y0: 0.310, y1: 0.700 } // dark centre
  }
};

/** Loader list for BootScene (mirrors tower/bird preload lists). */
export function hudPreloadList() {
  return Object.values(HUD_ART).map(({ key, file }) => ({ key, file }));
}

/* ------------------------------------------------------------------ */
/* Procedural stand-ins (same aspect + inner geometry as the artwork)   */
/* ------------------------------------------------------------------ */

const FALLBACK_COLORS = {
  edge: 0x4d3218, wood: 0xa4713d, woodLight: 0xc8905a,
  parch: 0xf7e8c9, parchShade: 0xdfc68f, dark: 0x3a2a18, darkEdge: 0x241a0e
};

/**
 * Draw a simple panel/button stand-in under `key` with the SAME trimmed
 * aspect and inner-window fractions as the supplied artwork. Called from
 * BootScene's loaderror handler (and defensively from the HUD) so the
 * layout code always deals with well-known geometry.
 */
export function ensureHudArtFallback(scene, key) {
  const T = scene.textures;
  if (T.exists(key)) return;
  const entry = Object.values(HUD_ART).find((a) => a.key === key);
  if (!entry) return;

  const H = 200;
  const W = Math.round(H * entry.aspect);
  const g = scene.add.graphics();
  const dark = key === 'hud-hearts-panel' || key === 'hud-score-panel'
    || key === 'hud-pause-btn' || key === 'hud-sound-btn';

  if (entry.iconDisk) {
    const c = W / 2, r = W / 2 - 2;
    g.fillStyle(FALLBACK_COLORS.edge, 1); g.fillCircle(c, c, r);
    g.fillStyle(FALLBACK_COLORS.wood, 1); g.fillCircle(c, c, r - 6);
    g.fillStyle(dark ? 0x6b4a26 : FALLBACK_COLORS.woodLight, 1);
    g.fillCircle(c, c, r - 12);
  } else {
    const i = entry.inner;
    g.fillStyle(FALLBACK_COLORS.edge, 1); g.fillRoundedRect(0, 0, W, H, 14);
    g.fillStyle(FALLBACK_COLORS.wood, 1); g.fillRoundedRect(4, 4, W - 8, H - 8, 11);
    g.fillStyle(dark ? FALLBACK_COLORS.darkEdge : FALLBACK_COLORS.parchShade, 1);
    g.fillRoundedRect(i.x0 * W, i.y0 * H, (i.x1 - i.x0) * W, (i.y1 - i.y0) * H, 9);
    g.fillStyle(dark ? FALLBACK_COLORS.dark : FALLBACK_COLORS.parch, 1);
    g.fillRoundedRect(i.x0 * W + 4, i.y0 * H + 4, (i.x1 - i.x0) * W - 8, (i.y1 - i.y0) * H - 8, 7);
    if (entry.cells) {
      g.fillStyle(FALLBACK_COLORS.edge, 0.85);
      for (const c of [entry.cells.question.x1, entry.cells.stars.x0]) {
        g.fillRoundedRect(c * W - 3, i.y0 * H, 6, (i.y1 - i.y0) * H, 3);
      }
    }
  }
  g.generateTexture(key, W, H);
  g.destroy();
}

/** Ensure every HUD art key exists (browser: preload; elsewhere: fallback). */
export function ensureAllHudArt(scene) {
  let missing = [];
  for (const { key } of hudPreloadList()) {
    if (!scene.textures.exists(key)) {
      ensureHudArtFallback(scene, key);
      missing.push(key);
    }
  }
  return missing;
}
